/* ---------- macros */

/* ---------- structures */

typedef struct
{
	int status;
	unsigned char type;
	unsigned char pixelDepth;
	short int width;
	short int height;
	unsigned long *imageData;
} tgaInfo;

struct gravy_layer	/* fake name */
{
	real width;
	real height;
	real x;
	real y;
	real half_width;
	real half_height;
	real distance;
};

struct gravy_rect	/* fake name */
{
	real x0;
	real y0;
	real x1;
	real y1;
};

